from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for serialized character-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Serialize a scalar using evaluator-compatible missing-value handling."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute LCP length with logarithmic prefix-slice comparisons."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return exact sorted-adjacent character-Trie reuse."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each row using its row-specific column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int) -> List[int]:
        """Rank columns by repeated serialized-value character mass."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            total_length = 0

            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeated = sum(
                count * (count - 1)
                for count in counts.values()
            )

            if mode == 0:
                key = weighted
            else:
                key = repeated * max(1, total_length // max(1, n))

            ranked.append((key, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _leaf_order(self, cells, rows, remaining, empty_columns) -> List[int]:
        """Put mask-empty fields in a deterministic tail after repeated fields."""
        if len(rows) < 2:
            return list(remaining)

        statistics = []

        for column in remaining:
            counts = {}
            nonempty = 0

            for row in rows:
                value = cells[row, column]
                counts[value] = counts.get(value, 0) + 1
                if value:
                    nonempty += 1

            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeated = sum(
                count * (count - 1)
                for count in counts.values()
            )

            # Empty fields contribute no characters.  For rows sharing a
            # missingness mask, moving those fields behind nonempty fields
            # exposes useful repeated prefixes.
            empty_tail = 1 if column in empty_columns else 0
            statistics.append((
                empty_tail,
                -weighted,
                -repeated,
                -nonempty,
                column,
            ))

        statistics.sort()
        return [item[-1] for item in statistics]

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Build one leading-value partition with bounded mask-specialized leaves."""
        n, m = cells.shape

        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        lead_stats = []

        for column in range(m):
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1

            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            lead_stats.append((weighted, column))

        lead_stats.sort(key=lambda item: (-item[0], item[1]))
        lead = lead_stats[0][1]
        remaining = [column for column in range(m) if column != lead]

        # Only the 24 columns with greatest repeated mass participate in masks.
        repeated_columns = []
        for column in remaining:
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1

            mass = sum(
                count * (count - 1)
                for count in counts.values()
            )
            repeated_columns.append((mass, column))

        repeated_columns.sort(key=lambda item: (-item[0], item[1]))
        mask_columns = [
            column for mass, column in repeated_columns[:24]
            if mass > 0
        ]

        # First partition by the selected leading field.
        lead_groups = {}
        for row in range(n):
            lead_groups.setdefault(cells[row, lead], []).append(row)

        result = [None] * n

        for group_rows in lead_groups.values():
            if len(group_rows) < 3 or not mask_columns:
                suffix = self._leaf_order(
                    cells, group_rows, remaining, set()
                )
                order = [lead] + suffix
                for row in group_rows:
                    result[row] = order[:]
                continue

            # Form missingness masks once per row in this leaf.
            mask_groups = {}
            for row in group_rows:
                mask = tuple(
                    index
                    for index, column in enumerate(mask_columns)
                    if cells[row, column] == ""
                )
                mask_groups.setdefault(mask, []).append(row)

            ranked_masks = sorted(
                mask_groups.items(),
                key=lambda item: (-len(item[1]), item[0])
            )

            # Keep at most twelve frequent masks.  Rare masks use one
            # deterministic residual suffix, preserving bounded work.
            assignments = []
            for mask, rows in ranked_masks[:12]:
                empty_columns = {
                    mask_columns[index] for index in mask
                }
                assignments.append((rows, empty_columns))

            if len(ranked_masks) > 12:
                residual = []
                for _, rows in ranked_masks[12:]:
                    residual.extend(rows)
                residual.sort()
                assignments.append((residual, set()))

            for rows, empty_columns in assignments:
                suffix = self._leaf_order(
                    cells, rows, remaining, empty_columns
                )
                order = [lead] + suffix
                for row in rows:
                    result[row] = order[:]

        return result

    def _candidate(self, cells, orders):
        """Serialize, score, and lexicographically sort one candidate."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row)
        )
        return score, row_order, strings

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best of two global orders and one mask-specialized order."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        conditional = self._conditional_orders(cells)

        candidates = (
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            conditional,
        )

        best = None
        for orders in candidates:
            score, row_order, strings = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))

            if best is None or choice > best[0]:
                best = (choice, row_order, strings, orders)

        _, row_order, _, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column] for column in source_order
            ]
            column_orders.append([
                df.columns[column] for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

